const body = $input.item.json.body;
const callback = body.callback_query;
const message = body.message;

let chatId = 0;
let fromId = 0;
let text = '';
let isCallback = false;
let callbackData = '';

if (callback) {
  isCallback = true;
  chatId = callback.message.chat.id;
  fromId = callback.from.id;
  callbackData = callback.data || '';
} else if (message) {
  chatId = message.chat.id;
  fromId = message.from.id;
  text = (message.text || '').trim();
}

// 1. Menu Utama Grup / Umum (Tanpa Barcode)
const mainKeyboard = {
  keyboard: [
    [{ text: "🙍‍♀️ CONTACT" }, { text: "🚫 🙅 Do Not Do" }, { text: "📋 RULES" }],
    [{ text: "🪪 Apply Member EL" }, { text: "⏰ Jam Ops" }],
    [{ text: "💵 Payment" }, { text: "💎 Price List EL" }]
  ],
  resize_keyboard: true
};

// 2. Menu Utama Khusus Private Chat / DM (Memiliki Tombol Barcode Masuk)
const mainKeyboardPrivate = {
  keyboard: [
    [{ text: "🎫 Barcode Masuk" }, { text: "💎 Price List EL" }],
    [{ text: "🙍‍♀️ CONTACT" }, { text: "🚫 🙅 Do Not Do" }, { text: "📋 RULES" }],
    [{ text: "🪪 Apply Member EL" }, { text: "⏰ Jam Ops" }, { text: "💵 Payment" }]
  ],
  resize_keyboard: true
};

// 3. Sub-Menu Cabang Pricelist (Termasuk Celeb & Diamond)
const branchKeyboard = {
  keyboard: [
    [{ text: "🏢 El Centro" }, { text: "🏢 El Spa Pangjay" }, { text: "🏢 El Seven" }],
    [{ text: "🏢 El Norte" }, { text: "🏢 El Fenix" }, { text: "🏢 El Spa Kelapa Gading" }],
    [{ text: "🏢 El Orca" }, { text: "🏢 El Cassa" }, { text: "🏢 El Memento" }],
    [{ text: "⭐ Price List Celeb & Diamond" }],
    [{ text: "🔙 Kembali" }]
  ],
  resize_keyboard: true
};

// 4. Sub-Menu Cabang Khusus Barcode
const barcodeBranchKeyboard = {
  keyboard: [
    [{ text: "🎫 Barcode El Centro" }, { text: "🎫 Barcode El Spa Pangjay" }, { text: "🎫 Barcode El Seven" }],
    [{ text: "🎫 Barcode El Norte" }, { text: "🎫 Barcode El Fenix" }, { text: "🎫 Barcode El Spa Kelapa Gading" }],
    [{ text: "🎫 Barcode El Orca" }, { text: "🎫 Barcode El Cassa" }, { text: "🎫 Barcode El Memento" }],
    [{ text: "⬅️ Kembali ke Menu Utama" }]
  ],
  resize_keyboard: true
};

// 5. Admin Inline Keyboard untuk Update Barcode
const adminInlineKeyboard = {
  inline_keyboard: [
    [
      { text: "🏢 El Centro", callback_data: "setbarcode:centro" },
      { text: "🏢 El Spa Pangjay", callback_data: "setbarcode:spaPangjay" }
    ],
    [
      { text: "🏢 El Seven", callback_data: "setbarcode:seven" },
      { text: "🏢 El Norte", callback_data: "setbarcode:norte" }
    ],
    [
      { text: "🏢 El Fenix", callback_data: "setbarcode:fenix" },
      { text: "🏢 El Spa Kelapa Gading", callback_data: "setbarcode:spaKelapaGading" }
    ],
    [
      { text: "🏢 El Orca", callback_data: "setbarcode:orca" },
      { text: "🏢 El Cassa", callback_data: "setbarcode:cassa" }
    ],
    [
      { text: "🏢 El Memento", callback_data: "setbarcode:memento" }
    ]
  ]
};

return {
  chatId,
  fromId,
  text,
  isCallback,
  callbackData,
  mainKeyboard,
  mainKeyboardPrivate,
  branchKeyboard,
  barcodeBranchKeyboard,
  adminInlineKeyboard
};
